def is_balanced(s):
    stack = []
    bracket_map = {")": "(", "}": "{", "]": "["}
    for c in s:
        if c in bracket_map.values():
            stack.append(c)
        elif c in bracket_map.keys():
            if not stack or stack.pop()!= bracket_map[c]:
                return False
    return not stack

def moving_average(numbers, window_size):
    if window_size > len(numbers):
        raise ValueError("Window size cannot be larger than the list of numbers")
    return [sum(numbers[i-window_size+1:i+1])/window_size for i in range(window_size-1, len(numbers))]

def flatten(nested_list):
    result = []
    for item in nested_list:
        if isinstance(item, list):
            result.extend(flatten(item))
        else:
            result.append(item)
    return result

def longest_common_prefix(strs):
    if not strs:
        return ""
    shortest_str = min(strs, key=len)
    for i, char in enumerate(shortest_str):
        for other in strs:
            if other[i]!= char:
                return shortest_str[:i]
    return shortest_str

